CREATE TABLE property_projects(id TEXT PRIMARY KEY,agency_id TEXT NOT NULL REFERENCES agencies(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 120),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),created_at TEXT NOT NULL,UNIQUE(agency_id,id));
CREATE INDEX property_projects_agency ON property_projects(agency_id,created_at,id);
CREATE TABLE project_items(agency_id TEXT NOT NULL,project_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('draft','job')),entity_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(agency_id,kind,entity_id),FOREIGN KEY(agency_id,project_id) REFERENCES property_projects(agency_id,id));
CREATE TABLE agency_templates(id TEXT PRIMARY KEY,agency_id TEXT NOT NULL REFERENCES agencies(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80),template_json TEXT NOT NULL CHECK(json_valid(template_json)),is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)),created_at TEXT NOT NULL,UNIQUE(agency_id,id));
CREATE UNIQUE INDEX agency_default_template ON agency_templates(agency_id) WHERE is_default=1;
CREATE TABLE client_reviews(id TEXT PRIMARY KEY,agency_id TEXT NOT NULL REFERENCES agencies(id),job_id TEXT NOT NULL REFERENCES generation_runs(job_id),manifest_hash TEXT NOT NULL CHECK(length(manifest_hash)=64),token_hash TEXT NOT NULL UNIQUE CHECK(length(token_hash)=64),status TEXT NOT NULL CHECK(status IN ('pending','commented','approved','revoked')),expires_at TEXT NOT NULL,approved_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX client_reviews_agency ON client_reviews(agency_id,created_at,id);
CREATE TABLE client_review_comments(id TEXT PRIMARY KEY,review_id TEXT NOT NULL REFERENCES client_reviews(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80),text TEXT NOT NULL CHECK(length(text) BETWEEN 1 AND 1500),time_seconds REAL CHECK(time_seconds BETWEEN 0 AND 40),created_at TEXT NOT NULL);
CREATE TRIGGER review_comments_limit BEFORE INSERT ON client_review_comments BEGIN SELECT RAISE(ABORT,'REVIEW_LIMIT') WHERE (SELECT count(*) FROM client_review_comments WHERE review_id=NEW.review_id)>=20; END;
CREATE TRIGGER review_version_immutable BEFORE UPDATE OF agency_id,job_id,manifest_hash,token_hash ON client_reviews BEGIN SELECT RAISE(ABORT,'REVIEW_VERSION_IMMUTABLE'); END;
CREATE TRIGGER project_editor_export AFTER INSERT ON editor_exports BEGIN INSERT OR IGNORE INTO project_items SELECT agency_id,project_id,'job',NEW.job_id,NEW.created_at FROM project_items WHERE agency_id=NEW.agency_id AND kind='draft' AND entity_id=NEW.import_id; END;
CREATE TRIGGER project_editor_export_retry AFTER UPDATE OF job_id ON editor_exports BEGIN INSERT OR IGNORE INTO project_items SELECT agency_id,project_id,'job',NEW.job_id,NEW.created_at FROM project_items WHERE agency_id=NEW.agency_id AND kind='draft' AND entity_id=NEW.import_id; END;
